'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var dgetrf = require( './../lib/dgetrf.js' );


// FIXTURES //

var POSITIVE_STRIDES_NO_OFFSET_1 = require( './fixtures/positive_stride_no_offset_1.json' ); // eslint-disable-line id-length
var POSITIVE_STRIDES_NO_OFFSET_2 = require( './fixtures/positive_stride_no_offset_2.json' ); // eslint-disable-line id-length


// FUNCTIONS //

function isApprox( t, actual, expected ) {
	var delta;
	var tol;
	var i;

	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		if ( actual[ i ] === expected[ i ] ) {
			t.strictEqual( actual[ i ], expected[ i ], 'returns expected value' );
		} else {
			delta = abs( actual[ i ] - expected[ i ] );
			tol = 2.0 * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance' );
		}
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgetrf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( dgetrf.length, 5, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided invalid dimensions or leading dimension', function test( t ) {
	var A = new Float64Array( 4 );
	var IPIV = new Int32Array( 2 );

	t.throws( function badRows() {
		dgetrf( -1, 2, A, 2, IPIV );
	}, RangeError, 'throws for a negative row count' );
	t.throws( function badColumns() {
		dgetrf( 2, -1, A, 2, IPIV );
	}, RangeError, 'throws for a negative column count' );
	t.throws( function badLeadingDimension() {
		dgetrf( 2, 2, A, 1, IPIV );
	}, RangeError, 'throws for an invalid leading dimension' );
	t.end();
});

tape( 'the function computes an `LU` factorization with partial pivoting', function test( t ) {
	var data = POSITIVE_STRIDES_NO_OFFSET_1;
	var A = new Float64Array( data.A );
	var IPIV = new Int32Array( data.IPIV );
	var info = dgetrf( data.M, data.N, A, data.strideA2, IPIV );

	t.strictEqual( info, data.expectedInfo, 'returns expected status code' );
	t.deepEqual( IPIV, new Int32Array( data.expectedIPIV ), 'returns expected pivot indices' );
	isApprox( t, A, new Float64Array( data.expectedA ) );
	t.end();
});

tape( 'the function supports tall matrices', function test( t ) {
	var data = POSITIVE_STRIDES_NO_OFFSET_2;
	var A = new Float64Array( data.A );
	var IPIV = new Int32Array( data.IPIV );
	var info = dgetrf( data.M, data.N, A, data.strideA2, IPIV );

	t.strictEqual( info, data.expectedInfo, 'returns expected status code' );
	t.deepEqual( IPIV, new Int32Array( data.expectedIPIV ), 'returns expected pivot indices' );
	isApprox( t, A, new Float64Array( data.expectedA ) );
	t.end();
});

tape( 'the function supports wide matrices', function test( t ) {
	var A = new Float64Array( [ 4.0, 2.0, 1.0, 3.0, 2.0, 1.0 ] );
	var IPIV = new Int32Array( 2 );
	var info = dgetrf( 2, 3, A, 2, IPIV );

	t.strictEqual( info, 0, 'returns expected status code' );
	t.deepEqual( IPIV, new Int32Array( [ 0, 1 ] ), 'returns expected pivot indices' );
	t.deepEqual( A, new Float64Array( [ 4.0, 0.5, 1.0, 2.5, 2.0, 0.0 ] ), 'returns expected factorization' );
	t.end();
});

tape( 'the function supports a 1-by-1 matrix and zero dimensions', function test( t ) {
	var A = new Float64Array( [ 5.0 ] );
	var IPIV = new Int32Array( 1 );

	t.strictEqual( dgetrf( 1, 1, A, 1, IPIV ), 0, 'returns expected status code' );
	t.deepEqual( A, new Float64Array( [ 5.0 ] ), 'returns expected factorization' );
	t.deepEqual( IPIV, new Int32Array( [ 0 ] ), 'returns expected pivot indices' );
	t.strictEqual( dgetrf( 0, 3, A, 1, IPIV ), 0, 'supports zero rows' );
	t.strictEqual( dgetrf( 3, 0, A, 3, IPIV ), 0, 'supports zero columns' );
	t.end();
});

tape( 'the function returns a non-zero status code for a singular matrix', function test( t ) {
	var A = new Float64Array( [ 0.0, 0.0, 1.0, 2.0 ] );
	var IPIV = new Int32Array( 2 );
	var info = dgetrf( 2, 2, A, 2, IPIV );

	t.strictEqual( info, 1, 'returns the first zero pivot index' );
	t.deepEqual( IPIV, new Int32Array( [ 0, 1 ] ), 'returns expected pivot indices' );
	t.end();
});
